insert into public.source_registry(key,name,category,source_tier,domain,connection_status,method,supports,limitations,action_url,coverage_notes) values ('cvm_dfp','CVM — Demonstrações Financeiras Padronizadas (DFP)','Demonstrações financeiras anuais','PRIMARY_OFFICIAL','dados.cvm.gov.br','CONNECTED_LIMITED','Arquivo anual oficial por ranges HTTP validados; BPA/BPP/DRE consolidados, contas selecionadas e última versão do exercício encerrado','["revenue","net_income","cash_balance","total_assets","current_assets","current_liabilities","equity"]'::jsonb,'Somente CNPJ emissor exato no DFP consolidado do exercício encerrado. Inclui controladas. Valores históricos, não posição atual ou patrimônio pessoal. Contas ausentes permanecem desconhecidas. Sem extração genérica de dívida. Limites de transferência/descompressão podem impedir a consulta.','https://dados.cvm.gov.br/dataset/cia_aberta-doc-dfp','Companhias emissoras cobertas pelo DFP; não cobre todas as empresas privadas. Sob demanda; padrão último ano encerrado.') on conflict(key) do nothing;
